#include <iostream>
using namespace std;

int* candle(int x[]) {
    static int w[2];
    w[0] = 0;
    w[1] = 0;

    while (x[0] != 0) {
        w[0] += x[0];
        w[1] += x[0] % x[1];
        x[0] /= x[1];
    }

    return w;
}

int main() {
    int a[2];
    cin >> a[0] >> a[1];

    int* c = candle(a);
    while (c[1] >= 5) {
        a[0] = c[1];
        c = candle(a);
    }

    cout << c[0];
    return 0;
}

